const { execFileSync } = require('child_process');
const fs = require('fs');
const EXE = '/workspace/dataset/test13_executable';
const OUT = '/workspace/probes/combinators.jsonl';

const D3='http://json-schema.org/draft-03/schema#';
const D4='http://json-schema.org/draft-04/schema#';
const D6='http://json-schema.org/draft-06/schema#';
const D7='http://json-schema.org/draft-07/schema#';
const D19='https://json-schema.org/draft/2019-09/schema';
const D20='https://json-schema.org/draft/2020-12/schema';
const DRAFTS=[D3,D4,D6,D7,D19,D20];

const pairs = [];
const add = (a,b)=>pairs.push([JSON.stringify(a), JSON.stringify(b)]);
const sweep = (a,b)=>{ add(a,b); for(const s of DRAFTS) add(a, Object.assign({"$schema":s}, b)); };

// --- allOf
sweep("ab", {allOf:[{type:"number"},{minLength:9},{maxLength:1}]});
add("ab", {allOf:[{type:"string"},{minLength:1}]});
add("ab", {allOf:[]});
sweep("ab", {allOf:[true,false,false]});
add("ab", {allOf:[false]});
add("ab", {allOf:[{allOf:[{minLength:9},{maxLength:1}]},{type:"number"}]});
add("ab", {allOf:[{anyOf:[{type:"number"},{minLength:9}]},{anyOf:[{type:"null"}]}]});
add("ab", {allOf:[{not:{type:"string"}},{not:{minLength:1}}]});
add({x:"a",y:"a"}, {allOf:[{properties:{x:{type:"number"},y:{type:"number"}}},{properties:{x:{minLength:9}}}]});
add("ab", {allOf:[{$ref:"#/$defs/a"}], $defs:{a:{minLength:9,maxLength:0}}});
add("ab", {$ref:"#/$defs/a", $defs:{a:{allOf:[{minLength:9},{maxLength:0}]}}});

// --- anyOf
sweep("ab", {anyOf:[{type:"number"},{minLength:9}]});
add("ab", {anyOf:[{type:"string"},{type:"number"}]});
sweep("ab", {anyOf:[]});
add("ab", {anyOf:[false,false]});
add("ab", {anyOf:[true]});
add("ab", {anyOf:[{allOf:[{type:"number"},{minLength:9}]},{type:"null"}]});
add("ab", {anyOf:[{minLength:9,maxLength:0,type:"number"}]});

// --- oneOf
sweep("ab", {oneOf:[{type:"string"},{minLength:1}]});
sweep("ab", {oneOf:[{type:"number"},{minLength:9},{maxLength:1}]});
add("ab", {oneOf:[{type:"string"},{type:"number"}]});
add("ab", {oneOf:[]});
add("ab", {oneOf:[true,true]});
add("ab", {oneOf:[false,false]});
add("ab", {oneOf:[true,false]});
add("ab", {oneOf:[{allOf:[{minLength:9},{maxLength:0}]},{type:"number"}]});
add("ab", {oneOf:[{type:"string"},{type:"string"},{type:"string"}]});

// --- not
sweep("ab", {not:{type:"string"}});
add("ab", {not:{type:"number"}});
add("ab", {not:true});
add("ab", {not:false});
add("ab", {not:{}});
add("ab", {not:{allOf:[{minLength:9},{maxLength:0}]}});
add("ab", {not:{minLength:9,maxLength:0,type:"number"}});

// --- if/then/else
sweep("ab", {if:{type:"string"},then:{minLength:9},else:{type:"number"}});
sweep("ab", {if:{type:"string"},then:{minLength:9,maxLength:1}});
sweep("ab", {if:{type:"number"},else:{minLength:9,maxLength:1}});
add("ab", {if:{type:"string"}});
add("ab", {if:{type:"number"},then:{minLength:9}});
add("ab", {then:{minLength:9},else:{maxLength:1}});
add("ab", {if:true,then:{minLength:9}});
add("ab", {if:false,else:{minLength:9}});
add("ab", {if:{type:"string"},then:false});
add("ab", {if:{type:"string"},then:true,else:false});
add("ab", {if:{},then:{type:"number"}});
add("ab", {if:{type:"string"},then:{allOf:[{minLength:9},{maxLength:0}]}});
add("ab", {if:{type:"string"},then:{anyOf:[{type:"number"}]}});
add("ab", {allOf:[{if:{type:"string"},then:{minLength:9}},{if:{type:"string"},then:{maxLength:0}}]});
add("ab", {if:{type:"string"},then:{if:{minLength:1},then:{maxLength:0,pattern:"^z"}}});
add("ab", {anyOf:[{if:{type:"string"},then:{minLength:9}}]});
add("ab", {not:{if:{type:"string"},then:{minLength:1}}});

// --- combinators under properties / items
add({x:1}, {properties:{x:{allOf:[{type:"string"},{minLength:9}]}}});
add(1, {properties:{x:{allOf:[{type:"string"},{minLength:9}]}}});
add({x:"a"}, {properties:{x:{allOf:[{type:"string"},{minLength:9},{maxLength:0}]}}});
add({x:"a",y:"b"}, {properties:{x:{allOf:[{minLength:9},{maxLength:0}]},y:{anyOf:[{type:"number"}]}}});
add({x:{y:"a"}}, {properties:{x:{properties:{y:{allOf:[{minLength:9},{maxLength:0}]}}}}});
add(["a","b"], {items:{allOf:[{minLength:9},{maxLength:0}]}});
add(["a","b"], {"$schema":D7, items:{allOf:[{minLength:9},{maxLength:0}]}});
add(["a","b"], {prefixItems:[{allOf:[{minLength:9},{maxLength:0}]}]});
add(["a","b"], {items:{oneOf:[{type:"number"},{type:"null"}]}});
add({x:"ab"}, {properties:{x:{if:{type:"string"},then:{minLength:9,maxLength:0}}}});
add({x:"ab"}, {properties:{x:{not:{type:"string"}}}});

// --- draft3 specific combinator analogs
add("ab", {"$schema":D3, disallow:"string"});
add("ab", {"$schema":D3, disallow:["string","number"]});
add("ab", {"$schema":D3, disallow:[{minLength:1}]});
add("ab", {"$schema":D3, extends:{minLength:9,maxLength:1}});
add("ab", {"$schema":D3, extends:[{minLength:9},{maxLength:1}]});
add("ab", {"$schema":D3, type:[{minLength:9},{maxLength:1}]});
add("ab", {"$schema":D3, allOf:[{type:"number"}], anyOf:[{type:"number"}], oneOf:[], not:{}, if:{}, then:{type:"number"}});
add("ab", {"$schema":D4, extends:{minLength:9}});

// --- dependent schemas / contains (conditional-ish)
add({a:1}, {dependentSchemas:{a:{minProperties:9,maxProperties:0}}});
add({a:1}, {"$schema":D7, dependencies:{a:{minProperties:9,maxProperties:0}}});
add([1,2], {contains:{type:"string"}});

// --- malformed (crash) cases
add("ab", {allOf:{type:"number"}});
add("ab", {anyOf:{type:"number"}});
add("ab", {oneOf:"x"});
add("ab", {allOf:[null]});
add("ab", {allOf:[1]});
add("ab", {anyOf:[null]});
add("ab", {not:[{type:"number"}]});
add("ab", {not:null});
add("ab", {not:1});
add("ab", {if:1,then:{minLength:9}});
add("ab", {if:{type:"string"},then:1});
add("ab", {oneOf:{a:{type:"number"}}});
add("ab", {allOf:"ab"});

const lines=[];
for (const [a,b] of pairs) {
  let out='', code=0;
  try { out = execFileSync(EXE, ['--a',a,'--b',b], {stdio:['ignore','pipe','ignore']}).toString(); }
  catch(e) { out = (e.stdout?e.stdout.toString():''); code = (e.status===null||e.status===undefined)?-1:e.status; }
  lines.push(JSON.stringify({a,b,out,exit:code}));
}
fs.writeFileSync(OUT, lines.join('\n')+'\n');
console.log('wrote', lines.length);
